mapper.select:
SELECT benefit_no
FROM benefit
WHERE plcy_no = #{plcyNo}

mapper.insert:
INSERT IGNORE INTO benefit_region (
benefit_no,
zip_cd
)
SELECT
#{benefitNo},
#{zipCd}
FROM DUAL
WHERE EXISTS (
SELECT 1
FROM region
WHERE zip_cd = #{zipCd}
)

INSERT INTO benefit_major (
benefit_no,
plcy_major_cd
) VALUES (
#{benefitNo},
#{plcyMajorCd}
)

INSERT INTO benefit_school (
benefit_no,
school_cd
) VALUES (
#{benefitNo},
#{schoolCd}
)

INSERT INTO benefit_job (
benefit_no,
job_cd
) VALUES (
#{benefitNo},
#{jobCd}
)

mapper.select:
SELECT COUNT(*)
FROM region
WHERE zip_cd = #{zipCd}

SELECT COUNT(*)
FROM benefit
WHERE plcy_no = #{plcyNo}
